using System;
using System.IO;
using System.Text;
using System.Text.Json;
using System.Threading.Tasks;
using FluentAssertions;
using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;
using Xunit;
using CampusEats.Features.Menu;
using CampusEats.Persistence;
using CampusEats.Exceptions;

namespace CampusEats.Tests.Features.Menu;

public class GetByIdMenuItemHandlerTests
{
    private DbContextOptions<CampusEatsContext> CreateOptions(string dbName) =>
        new DbContextOptionsBuilder<CampusEatsContext>()
            .UseInMemoryDatabase(dbName)
            .Options;

    [Fact]
    public async Task GivenExistingMenuItem_WhenHandle_ReturnsOkWithMenuItem()
    {
        // Arrange
        var dbName = Guid.NewGuid().ToString();
        var options = CreateOptions(dbName);

        var id = Guid.NewGuid();
        await using (var context = new CampusEatsContext(options))
        {
            context.MenuItems.Add(new MenuItem(id, "Burger", 9.99m));
            await context.SaveChangesAsync();
        }

        await using var ctx = new CampusEatsContext(options);
        var handler = new GetByIdMenuItemHandler(ctx);
        var request = new GetByIdMenuItemRequest(id);

        // Act
        var result = await handler.Handle(request);

        // Execute IResult into a HttpContext to inspect response
        var httpContext = new DefaultHttpContext();
        httpContext.Response.Body = new MemoryStream();

        await result.ExecuteAsync(httpContext);

        httpContext.Response.StatusCode.Should().Be(200);

        httpContext.Response.Body.Seek(0, SeekOrigin.Begin);
        var body = await new StreamReader(httpContext.Response.Body, Encoding.UTF8).ReadToEndAsync();
        var optionsJson = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
        var returned = JsonSerializer.Deserialize<MenuItem>(body, optionsJson);

        returned.Should().NotBeNull();
        returned!.Id.Should().Be(id);
        returned.Name.Should().Be("Burger");
        returned.Price.Should().Be(9.99m);
    }

    [Fact]
    public async Task GivenMissingMenuItem_WhenHandle_ThrowsMenuItemNotFoundException()
    {
        // Arrange
        var options = CreateOptions(Guid.NewGuid().ToString());
        await using var context = new CampusEatsContext(options);

        var handler = new GetByIdMenuItemHandler(context);
        var request = new GetByIdMenuItemRequest(Guid.NewGuid());

        // Act & Assert
        await Assert.ThrowsAsync<MenuItemNotFoundException>(() => handler.Handle(request));
    }
}
